<script>
document.addEventListener("DOMContentLoaded", function () {

  const valeurInitiale = 55354;
  const tauxParMinute = 0.006508;
  const dateReference = new Date("2025-12-31T23:59:00");

  function calculerValeur() {

    const maintenant = new Date();
    const diffMinutes = (maintenant - dateReference) / 60000;

    return valeurInitiale + (diffMinutes * tauxParMinute);

  }

  function updateCounter() {

    const valeur = calculerValeur();

    const texte = valeur
      .toFixed(5)
      .replace(".", ",");

    document
      .querySelectorAll(".sidex-co2-depuis-2006")
      .forEach(el => {

        el.textContent = texte;

      });

  }

  updateCounter();

  setInterval(updateCounter, 1000);

});
</script></div><div id="code_block-504-69" class="ct-code-block"><?= the_field("header_libelle_tonnes_ges", "option"); ?></div></div><?php if (sx_compare(sx_fn('get_field', 'header_texte_promo', 'option'), 'is_not_blank', '')) : ?><a id="link_text-424-69" class="ct-link-text link-promo c-transition c-link-accent" href="<?php echo esc_attr(sx_fn('get_field', 'header_lien_promo', 'option')); ?>" target="_self"><span id="span-425-69" class="ct-span"><?php echo sx_kses(sx_fn('get_field', 'header_texte_promo', 'option')); ?></span></a><?php endif; ?></div><div id="_header_center-15-69" class="oxy-header-center" ></div><div id="_header_right-16-69" class="oxy-header-right" ><div id="-pro-menu-166-69" class="oxy-pro-menu menu-secondaire " ><div class="oxy-pro-menu-mobile-open-icon " data-off-canvas-alignment=""><svg id="-pro-menu-166-69-open-icon"><use xlink:href="#Lineariconsicon-menu"></use></svg></div>

                
